#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

struct Query {
    int a, b, o;
};

int main() {
    int H, W, q;
    while (scanf("%d %d %d", &H, &W, &q) == 3 && H) {
        int ans = 0;
        vector<Query> queries(q);

        for (int i = 0; i < q; ++i) 
            scanf("%d %d %d", &queries[i].a, &queries[i].b, &queries[i].o);

        vector<bool> rowUsed(H, false), colUsed(W, false);

        for (int i = q - 1; i >= 0; --i) {
            if (queries[i].a == 0) {
                if (!colUsed[queries[i].b] && queries[i].o) 
                    ans += W - count(rowUsed.begin(), rowUsed.end(), true);
                colUsed[queries[i].b] = true;
            } else {
                if (!rowUsed[queries[i].b] && queries[i].o) 
                    ans += H - count(colUsed.begin(), colUsed.end(), true);
                rowUsed[queries[i].b] = true;
            }
        }
        printf("%d\n", ans);
    }
}

